def norm(x):
    return re.sub(r'\s+', ' ', str(x).lower()).strip()

def add(dst, vals):
    for v in vals:
        if v not in dst:
            dst.append(v)
    return dst

def info_ref(t):
    return bool(re.search(r'\b(?:confidential information|confidential materials?|such confidential information|such information|the information)\b', t))

def roles(t):
    emp = bool(re.search(r'\b(?:employees?|staff|personnel)\b', t))
    ext = bool(re.search(r'\b(?:consultants?|contractors?|agents?|professional advisers?|professional advisors?|legal advisers?|legal advisors?|financial advisers?|financial advisors?|accountants?|attorneys?|lawyers?|outside counsel|legal counsel|auditors?|lenders?)\b', t))
    rep = bool(re.search(r'\brepresentatives?\b', t))
    return emp, ext, rep

def rep_definition(t):
    if not re.search(r'\brepresentatives?\b', t):
        return False
    return bool(re.search(r'\brepresentatives?\b.{0,35}\b(?:means?|shall mean|includes?|refers? to)\b', t) or re.search(r'\([\"\' ]*representatives?[\"\' ]*\)', t))

def cut_target(t):
    end = min(len(t), 500)
    stops = [' provided that ', ' provided, however', ' on the condition ', ' on condition ', ' but only ', ' who have ', ' who need ', ' who are ', ' each bound ', ' and that ', ';', '.']
    for s in stops:
        p = t.find(s)
        if p >= 1 and p < end:
            end = p
    return t[:end]

def permission_segments(t):
    out = []
    pat = r'\b(?:may|can)\s+(?:use\s+and\s+)?(?:internally\s+)?(?:disclose|share|provide|release|transmit|give|make available|allow access)\b'
    for m in re.finditer(pat, t):
        phrase = m.group(0)
        if 'internally share' in phrase:
            out.append('__internal__')
        else:
            tail = t[m.end():m.end() + 650]
            p = tail.find(' to ')
            if p >= 0:
                out.append(cut_target(tail[p + 4:]))
    for m in re.finditer(r'\brestrict(?:s|ed|ing)?\s+access\b[^.;]{0,90}\bto\b', t):
        out.append(cut_target(t[m.end():m.end() + 500]))
    ep = r'\bnot\b[^.;]{0,320}\b(?:disclose|share|provide|release|transmit|divulge|communicate)\b[^.;]{0,260}\bexcept(?:\s+in\s+confidence)?\s+to\b'
    for m in re.finditer(ep, t):
        out.append(cut_target(t[m.end():m.end() + 500]))
    op = r'\bnot\b[^.;]{0,320}\b(?:disclose|share|provide|release|transmit|divulge|communicate)\b[^.;]{0,260}\bother\s+than\b'
    for m in re.finditer(op, t):
        out.append(cut_target(t[m.end():m.end() + 500]))
    return out

def operative_permission(t):
    if not info_ref(t):
        return False
    if not permission_segments(t):
        return False
    bad = re.search(r'\b(?:disclosing|originating) party\b[^.;]{0,90}\bmay\s+(?:disclose|share|provide)', t)
    good = re.search(r'\b(?:receiving party|recipient|each party|either party|participating entity|volunteer)\b', t)
    return not bool(bad and not good)

def wrong_employee_owner(t):
    return bool(re.search(r'\b(?:disclosing|originating|other)\s+party[\'’]?s\b[^.;]{0,90}\bemployees?\b', t) or re.search(r'\bemployees?\s+of\s+(?:the\s+)?(?:disclosing|originating|other)\s+party\b', t) or re.search(r'\baffiliates?[\'’]\s*[^.;]{0,80}\bemployees?\b', t))

def wrong_rep_owner(t):
    return bool(re.search(r'\b(?:disclosing|originating|other)\s+party[\'’]?s\s+representatives?\b', t) or re.search(r'\brepresentatives?\s+of\s+(?:the\s+)?(?:disclosing|originating|other)\s+party\b', t))

def context_ids(spans, i, ids):
    out = list(ids)
    for j in range(i - 1, max(-1, i - 9), -1):
        t = norm(spans[j].get('text', ''))
        if re.search(r'\b(?:undertakes?\s+in\s+relation|further\s+promises?\s+and\s+agrees?|each\s+party\s+agrees|entity\s+agrees)\b', t):
            v = spans[j].get('id')
            if v not in out:
                out = [v] + out
            break
    return out

def functional_exception(t):
    return bool(re.search(r'\bexcept\b[^.;]{0,220}\brequired\b[^.;]{0,180}\b(?:purpose|business relationship|obligations?|service)\b', t))

def prohibition_target(t, task_id):
    if not info_ref(t):
        return False
    verb = r'(?:disclos(?:e|ed|ing)|shar(?:e|ed|ing)|provid(?:e|ed|ing)|releas(?:e|ed|ing)|transmit(?:ted|ting)?|divulg(?:e|ed|ing)|communicat(?:e|ed|ing)|transfer(?:red|ring)?)'
    if task_id == 'nda-7':
        target = r'(?:third[- ]part(?:y|ies)|any\s+other\s+person|any\s+other\s+organization)'
    else:
        target = r'(?:(?:its|their|receiving party[\'’]s)\s+)?employees?'
    pat = r'\b(?:shall\s+|will\s+|must\s+|may\s+)?not\b[^.;]{0,280}\b' + verb + r'\b[^.;]{0,300}\b' + target + r'\b'
    pat2 = r'\b(?:agrees?\s+not\s+to|prohibited\s+from)\b[^.;]{0,260}\b' + verb + r'\b[^.;]{0,300}\b' + target + r'\b'
    if not (re.search(pat, t) or re.search(pat2, t)):
        return False
    if functional_exception(t):
        return False
    p = t.find(' not ')
    if p < 0:
        p = t.find('prohibited')
    pre = t[:p] if p >= 0 else t
    bad = max(pre.rfind('disclosing party'), pre.rfind('originating party'))
    good = max(pre.rfind('receiving party'), pre.rfind('recipient'), pre.rfind('each party'), pre.rfind('either party'), pre.rfind('volunteer'), pre.rfind('participating entity'), pre.rfind('representatives'))
    return not (bad >= 0 and bad > good)

def relevant(spans, task_id):
    out = []
    for s in spans:
        t = norm(s.get('text', ''))
        emp, ext, rep = roles(t)
        verb = bool(re.search(r'\b(?:disclose|disclosed|disclosing|share|shared|divulge|communicate|provide|release|transmit|transfer|access)\b', t))
        role = emp or rep if task_id == 'nda-5' else ext or rep or bool(re.search(r'\bthird[- ]part(?:y|ies)\b', t))
        if info_ref(t) and verb and role:
            add(out, [s.get('id')])
            if len(out) >= 8:
                break
    if not out:
        for s in spans:
            t = norm(s.get('text', ''))
            if info_ref(t) and re.search(r'\b(?:confidential|disclose|disclosure)\b', t):
                add(out, [s.get('id')])
                if len(out) >= 4:
                    break
    return out

def apply(inputs, premises):
    task_id = inputs.get('task_id') if isinstance(inputs, dict) else None
    if task_id not in ['nda-5', 'nda-7'] or not isinstance(premises, dict):
        return {'handled': False, 'answer': None, 'used_span_ids': []}
    spans = premises.get('source_spans')
    if not isinstance(spans, list) or not spans:
        return {'handled': False, 'answer': None, 'used_span_ids': []}
    defs = []
    for s in spans:
        t = norm(s.get('text', ''))
        if rep_definition(t):
            emp, ext, rep = roles(t)
            defs.append((s.get('id'), emp, ext))
    ent5 = []
    ent7 = []
    n = len(spans)
    for size in [1, 2]:
        for i in range(0, n - size + 1):
            parts = []
            ids = []
            for j in range(i, i + size):
                parts.append(norm(spans[j].get('text', '')))
                ids.append(spans[j].get('id'))
            t = ' '.join(parts)
            if not operative_permission(t):
                continue
            for seg in permission_segments(t):
                emp, ext, rep = roles(seg)
                if seg == '__internal__':
                    emp = True
                if re.search(r'\ball\s+such\s+employees?\b', t):
                    emp = True
                if wrong_employee_owner(seg):
                    emp = False
                if wrong_rep_owner(seg):
                    rep = False
                p5 = context_ids(spans, i, ids)
                p7 = context_ids(spans, i, ids)
                if rep:
                    for did, de, dx in defs:
                        if de and not emp:
                            emp = True
                            add(p5, [did])
                        if dx and not ext:
                            ext = True
                            add(p7, [did])
                if emp and not ent5:
                    ent5 = p5
                if ext and not ent7:
                    ent7 = p7
    if task_id == 'nda-5' and ent5:
        return {'handled': True, 'answer': 'Entailment', 'used_span_ids': ent5}
    if task_id == 'nda-7' and ent7:
        return {'handled': True, 'answer': 'Entailment', 'used_span_ids': ent7}
    for i, s in enumerate(spans):
        t = norm(s.get('text', ''))
        if prohibition_target(t, task_id):
            ids = context_ids(spans, i, [s.get('id')])
            return {'handled': True, 'answer': 'Contradiction', 'used_span_ids': ids}
    ids = relevant(spans, task_id)
    if not ids:
        return {'handled': False, 'answer': None, 'used_span_ids': []}
    return {'handled': True, 'answer': 'NotMentioned', 'used_span_ids': ids}

